function validate(input) {
  const [{ Employees = [] }] = input;
  const keys = new Set(), visits = new Map();
  for (const [emp, day, start, end] of Employees) {
    if (emp === null || day === null || start === null || end === null) return 'Employees rows may not contain null.';
    if (!/^\d{4}-\d{2}-\d{2}$/.test(day)) return `event_day ${day} is not a YYYY-MM-DD date.`;
    if (start < 1 || end > 1440 || start >= end) return `Visit ${start}-${end} must satisfy 1 <= in_time < out_time <= 1440.`;
    const key = `${emp}|${day}|${start}`;
    if (keys.has(key)) return `(${emp}, ${day}, ${start}) appears twice.`;
    keys.add(key);
    const bucket = `${emp}|${day}`;
    if (!visits.has(bucket)) visits.set(bucket, []);
    visits.get(bucket).push([start, end]);
  }
  for (const [bucket, list] of visits) {
    list.sort((a, b) => a[0] - b[0]);
    for (let i = 1; i < list.length; i++) if (list[i][0] <= list[i - 1][1]) return `Visits of ${bucket.replace('|', ' on ')} overlap.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = (n) => Math.floor(rand() * n);
  const emps = small ? 3 : 50;
  const days = small ? 3 : 20;
  const rows = small ? pick(9) : 2000;
  // Spread the visits over (employee, day) buckets, then give each bucket disjoint intervals.
  const counts = new Map();
  for (let k = 0; k < rows; k++) {
    const bucket = `${1 + pick(emps)}|${1 + pick(days)}`;
    counts.set(bucket, (counts.get(bucket) ?? 0) + 1);
  }
  const Employees = [];
  for (const [bucket, k] of counts) {
    const [emp, d] = bucket.split('|').map(Number);
    // Days run from 2021-01-28 across the month boundary into February.
    const date = d + 27 <= 31 ? `2021-01-${d + 27}` : `2021-02-${String(d - 4).padStart(2, '0')}`;
    const points = new Set();
    while (points.size < 2 * k) {
      const r = rand();
      points.add(small && r < 0.1 ? 1 : small && r < 0.2 ? 1440 : 1 + pick(1440));
    }
    const sorted = [...points].sort((a, b) => a - b);
    for (let i = 0; i < k; i++) Employees.push([emp, date, sorted[2 * i], sorted[2 * i + 1]]);
  }
  // Shuffle so rows of one bucket are not adjacent.
  for (let i = Employees.length - 1; i > 0; i--) { const j = pick(i + 1); [Employees[i], Employees[j]] = [Employees[j], Employees[i]]; }
  return [{ Employees }];
}
